// 8001295C
f32 dAcNpc_c::calcDistXZ(const dActor_c *actor, const mVec3_c *pos) const {
    f32 dist = 0.0f;
    if (pos == NULL) {
        pos = &mPos;
    }
    if (actor != NULL) {
        mVec3_c d = *pos - *actor->getPosP();
        dist = EGG::Mathf::sqrt(d.x * d.x + d.z * d.z);
    }
    return dist;
}

// 800129BC
f32 dAcNpc_c::calcPlayerDistXZ(int player, const mVec3_c *pos) const {
    return calcDistXZ(fn_800FBC84(player), pos);
}

// 80012A08
int dAcNpc_c::searchPlayer(u32 player, BOOL checkGround, int exclude, BOOL nearest, const mVec3_c *pos, f32 range) const {
    if (player > 4) {
        return 4;
    }

    int no = player;
    int start = no;
    if (no == 4) {
        start = 0;
    }
    int end = no + 1;
    if (no == 4) {
        end = 4;
    }

    f32 best = range;
    f32 groundY = 0.0f;
    int found = 4;
    if (checkGround) {
        const mVec3_c *p = pos != NULL ? pos : &mPos;
        if (p != NULL) {
            groundY = dBGCF::getGroundY(p, FALSE);
        }
    }

    for (int i = start; i < end; i++) {
        if (i == exclude) {
            continue;
        }
        dPlayerActor_c *pl = fn_800FBC84(i);
        if (pl == NULL) {
            continue;
        }
        f32 dist = calcDistXZ(pl, pos);
        if (dist < best) {
            BOOL ok = TRUE;
            if (checkGround && std::fabs(pl->mPos.y - groundY) >= 48.0f) {
                ok = FALSE;
            }
            if (ok) {
                if (!nearest) {
                    return i;
                }
                found = i;
                best = dist;
            }
        }
    }
    return found;
}

// 80012B7C
BOOL dAcNpc_c::isPlayerNear(u32 player, BOOL checkGround, const mVec3_c *pos, f32 range) const {
    return searchPlayer(player, checkGround, 4, FALSE, pos, range) != 4;
}

