BOOL dAcNpc_c::calcOfsPos(mVec3_c *out, const mVec3_c *ofs) {
    mVec3_c pos;
    pos = *ofs;
    pos.rotY(mAngle3D.y);
    pos += mPos;
    if (!frontChk_c::checkStep(&pos, 0.0f, NULL)) {
        *out = pos;
        return TRUE;
    }
    return FALSE;
}

// 80012CFC
int dAcNpc_c::getSidePos(mVec3_c *out) {
    u8 flags = mFrontChk.mHitFlags;
    int ret = 0;
    *out = mPos;
    switch (flags) {
    case 3:
        ret = 1;
        break;
    case 1:
        if (calcOfsPos(out, &l_80564BC0[1])) {
            ret = 2;
        } else {
            ret = 1;
        }
        break;
    case 2: {
        BOOL ok = calcOfsPos(out, &l_80564BC0[0]);
        ret = 1;
        if (ok) {
            ret = 2;
        }
        break;
    }
    }
    return ret;
}

