// 80012FE8
int dAcNpc_c::requestPermit(int type, u32 player, BOOL arg) {
    int ret = 7;
    switch (type) {
    case 4:
        if (player != 4) {
            setPermitOwner(player);
            ret = 0;
        } else if (isLocalOwner()) {
            setPermitOwner(fn_800DCF58());
            ret = 1;
        }
        break;
    case 1:
    case 2:
    case 3:
        if (player != 4 && (int)player != fn_800DCF58()) {
            setPermitState(player);
            ret = 2;
        } else if (isLocalOwner()) {
            setPermitStateSelf();
            ret = 3;
        }
        break;
    case 9:
        if (player == 4) {
            if (!isMultiPlay()) {
                ret = 4;
            } else {
                setPermitFlagSelf();
                ret = 5;
            }
        }
        break;
    case 6:
        if (isInUse(NULL) && isLocalOwner()) {
            int owner = 4;
            int other = 4;
            if (getPermitPlayers(&owner, &other)) {
                if ((player != 4 && (int)player == other) || player == 4) {
                    if (arg) {
                        fn_800134A4();
                    }
                    ret = 6;
                }
            }
        }
        break;
    }
    return ret;
}

