// 80013730
BOOL dAcNpc_c::getPermitPlayers(int *owner, int *player) const {
    if (fn_800EFE6C(&mNpcItem.mId)) {
        dNpcPermit_c *permit = fn_800F54E0(&mNpcItem);
        if (permit != NULL) {
            u8 state = permit->mState;
            u8 other = permit->_2;
            if (state < 4) {
                *owner = state;
                *player = state;
                return TRUE;
            }
            if (other < 4) {
                *player = other;
                return TRUE;
            }
        }
    }
    return FALSE;
}

// 800137C8
BOOL dAcNpc_c::isInUse(int *player) const {
    if (!isNetSync()) {
        return mTalk.isBusy();
    }
    int owner = 4;
    int tmp = 4;
    if (player == NULL) {
        player = &tmp;
    }
    *player = 4;
    if (getPermitPlayers(&owner, player) && *player < 4) {
        return TRUE;
    }
    return FALSE;
}

// 80013864
