// ---- dAcNpc_c: free unit / position search helpers (80014084..800155D0) ----

static inline const dItem::Item *ptrTo(const dItem::Item &item) {
    return &item;
}

static inline bool isFreePos(const mVec3_c *pos, BOOL checkA) {
    dItem::Item item((u16)0xFFF1);
    return fn_800F20D0(pos, &item, NULL, 0x44, TRUE, checkA);
}

static inline bool isFreeUnit(int x, int z) {
    dItem::Item item((u16)0xFFF1);
    return fn_800F1DF0(x, z, &item, NULL, 0x44, TRUE, TRUE);
}

BOOL dAcNpc_c::searchFreeSideAngle(mAng *pAngle, const mVec3_c *pCenter, BOOL twoPass) {
    static const mVec3_c offs[4] = {
        mVec3_c(0.0f, 0.0f, -32.0f),
        mVec3_c(0.0f, 0.0f, 32.0f),
        mVec3_c(-32.0f, 0.0f, 0.0f),
        mVec3_c(32.0f, 0.0f, 0.0f),
    };
    static const mAng ang[4] = {mAng(-0x8000), mAng(0), mAng(-0x4000), mAng(0x4000)};

    u32 cnt = 0;
    for (int pass = 1; pass >= !twoPass; pass--) {
        BOOL checkA = pass != 0;
        for (u32 i = 0; i < 4; i++) {
            mVec3_c p = *pCenter + offs[i];
            if (isFreePos(&p, checkA)) {
                f32 chance = 100.0f / (cnt + 1);
                if (cM::rndF(100.0f) <= chance) {
                    *pAngle = ang[i];
                }
                cnt++;
            }
        }
        if (pass != 0 && cnt != 0) {
            break;
        }
    }
    return cnt != 0;
}

int dAcNpc_c::getSingleDir(int dirBits) {
    if (countDirBits(dirBits) != 1) {
        return 4;
    }
    for (int i = 0; i < 4; i++) {
        if ((dirBits >> i) & 1) {
            return i;
        }
    }
    return 4;
}

u32 dAcNpc_c::countDirBits(int dirBits) {
    u32 n = 0;
    for (int i = 0; i < 4; i++) {
        if ((dirBits >> i) & 1) {
            n++;
        }
    }
    return n;
}

u32 dAcNpc_c::dirToBit(u32 dir) {
    u32 bit = 0;
    if (dir < 4) {
        bit = 1 << dir;
    }
    return bit;
}

int dAcNpc_c::getFreeDirToward(int tgtX, int tgtZ, int unitX, int unitZ) {
    int dx = tgtX - unitX;
    int dz = tgtZ - unitZ;
    if (labs(dx) >= labs(dz)) {
        if (dx > 0) {
            if (isFreeUnit(unitX + 1, unitZ)) {
                return 3;
            }
        } else if (dx < 0) {
            if (isFreeUnit(unitX - 1, unitZ)) {
                return 1;
            }
        }
        if (dz > 0) {
            if (isFreeUnit(unitX, unitZ + 1)) {
                return 2;
            }
        } else if (dz < 0) {
            if (isFreeUnit(unitX, unitZ - 1)) {
                return 0;
            }
        }
    } else {
        if (dz > 0) {
            if (isFreeUnit(unitX, unitZ + 1)) {
                return 2;
            }
        } else if (dz < 0) {
            if (isFreeUnit(unitX, unitZ - 1)) {
                return 0;
            }
        }
        if (dx > 0) {
            if (isFreeUnit(unitX + 1, unitZ)) {
                return 3;
            }
        } else if (dx < 0) {
            if (isFreeUnit(unitX - 1, unitZ)) {
                return 1;
            }
        }
    }
    return 4;
}

u32 dAcNpc_c::getFreeDirBitsToward(int tgtX, int tgtZ, int unitX, int unitZ) {
    u32 bits = 0;
    int dx = tgtX - unitX;
    int dz = tgtZ - unitZ;
    if (dx > 0) {
        if (isFreeUnit(unitX + 1, unitZ)) {
            bits = dirToBit(3);
        }
    } else if (dx < 0) {
        if (isFreeUnit(unitX - 1, unitZ)) {
            bits = dirToBit(1);
        }
    }
    if (dz > 0) {
        if (isFreeUnit(unitX, unitZ + 1)) {
            bits |= dirToBit(2);
        }
    } else if (dz < 0) {
        if (isFreeUnit(unitX, unitZ - 1)) {
            bits |= dirToBit(0);
        }
    }
    return bits;
}

BOOL dAcNpc_c::searchPosNear(mVec3_c *pPos, const mVec3_c *pCenter, f32 minDist, f32 maxDist) {
    mAng sideAng = 0;
    BOOL attr = isCurrentSceneAttr(1);
    int end = !attr;
    if (!searchFreeSideAngle(&sideAng, pCenter, attr)) {
        return FALSE;
    }

    f32 range;
    if (minDist < maxDist) {
        range = maxDist - minDist;
    } else {
        range = minDist - maxDist;
    }

    mAng a;
    BOOL checkA;
    bool ok;
    for (int pass = 1; pass >= end; pass--) {
        checkA = pass != 0;
        for (int i = 0; i < 9; i++) {
            f32 dist = minDist + cM::rndF(range);
            mVec3_c p = mVec3_c::Zero;
            a = cM::rndInt(0x2000);
            if (cM::rndInt(4) & 1) {
                a = -a;
            }
            a += sideAng;
            p.x = pPos->x + dist * mAng(a).sin();
            p.z = pPos->z + dist * mAng(a).cos();
            dFdBase_c::snapToUnitCenter(&p, &p);
            p.y = dBGCF::getGroundY(&p, FALSE);

            ok = false;
            if (std::fabs(pCenter->y - p.y) < 48.0f) {
                dItem::Item item((u16)0xFFF1);
                dNpc::holeCheck_e holeCheck = dNpc::CHECK_HOLES;
                if (fn_800F20D0(&p, &item, NULL, 0x44, holeCheck, checkA)) {
                    ok = true;
                }
            }
            if (ok) {
                pPos->x = p.x;
                pPos->z = p.z;
                return TRUE;
            }
            if (range > 32.0f) {
                range -= 32.0f;
            }
        }
    }
    return FALSE;
}

BOOL dAcNpc_c::isFreeBeyond(const mVec3_c *pPos, const mVec3_c *pTarget, BOOL checkA) {
    mAng a = dActor_c::targetAngleY(pTarget, pPos);
    mVec3_c v(0.0f, 0.0f, 32.0f);
    v.rotY(a);
    mVec3_c p = *pTarget + v;
    if (isFreePos(&p, checkA)) {
        return TRUE;
    }
    return FALSE;
}

BOOL dAcNpc_c::searchPosInCircle(mVec3_c *pPos, const mVec3_c *pBase, const mVec3_c *pTarget, f32 radius, f32 minDist, f32 maxDist) {
    if (minDist == maxDist) {
        return FALSE;
    }
    if (minDist > maxDist) {
        f32 tmp = minDist;
        minDist = maxDist;
        maxDist = tmp;
    }

    BOOL attr = isCurrentSceneAttr(1);
    for (int pass = 1; pass >= !attr; pass--) {
        BOOL checkA = pass != 0;
        for (int i = 0; i < 9; i++) {
            f32 r = cM::rndF(radius);
            mVec3_c p = mVec3_c::Zero;
            mAng a = cM::rndInt(0xFFFF);
            p.x = pBase->x + r * a.sin();
            p.z = pBase->z + r * a.cos();
            f32 dist = (p - *pTarget).xzLen();
            if (dist > minDist && isFreeBeyond(&p, pTarget, checkA)) {
                if (dist > maxDist) {
                    dist = maxDist;
                }
                f32 d = minDist + cM::rndF(dist - minDist);
                mVec3_c v(0.0f, 0.0f, 1.0f);
                mAng ang = dActor_c::targetAngleY(pTarget, &p);
                mVec3_c q = mVec3_c::Zero;
                v.rotY(ang);
                v *= d;
                mVec3_c sum = *pTarget + v;
                q = sum;
                dFdBase_c::snapToUnitCenter(&q, &q);
                q.y = dBGCF::getGroundY(&q, FALSE);

                bool ok = false;
                if (std::fabs(pTarget->y - q.y) < 48.0f) {
                    dNpc::holeCheck_e holeCheck = dNpc::CHECK_HOLES;
                    if (fn_800F20D0(&q, ptrTo(dItem::Item((u16)0xFFF1)), NULL, 0x44, holeCheck, checkA)) {
                        ok = true;
                    }
                }
                if (ok) {
                    pPos->x = q.x;
                    pPos->z = q.z;
                    return TRUE;
                }
            }
        }
    }
    return FALSE;
}

BOOL dAcNpc_c::searchPosInRect(mVec3_c *pPos, const mVec3_c *pTarget, f32 x0, f32 z0, f32 x1, f32 z1, f32 minDist, f32 maxDist) {
    bool ok;
    int pass;
    BOOL checkA;
    int i;
    if (minDist == maxDist) {
        return FALSE;
    }
    if (x0 > x1) {
        f32 tmp = x0;
        x0 = x1;
        x1 = tmp;
    }
    if (z0 > z1) {
        f32 tmp = z0;
        z0 = z1;
        z1 = tmp;
    }
    f32 w = x1 - x0;
    f32 h = z1 - z0;
    if (w <= 0.0f || h <= 0.0f) {
        return FALSE;
    }
    if (minDist > maxDist) {
        f32 tmp = minDist;
        minDist = maxDist;
        maxDist = tmp;
    }

    BOOL attr = isCurrentSceneAttr(1);
    for (pass = 1; pass >= !attr; pass--) {
        checkA = pass != 0;
        for (i = 0; i < 9; i++) {
            mVec3_c p = mVec3_c::Zero;
            p.x = x0 + cM::rndF(w);
            p.z = z0 + cM::rndF(h);
            f32 dist = (p - *pTarget).xzLen();
            if (dist > minDist && isFreeBeyond(&p, pTarget, checkA)) {
                if (dist > maxDist) {
                    dist = maxDist;
                }
                f32 d = minDist + cM::rndF(dist - minDist);
                mVec3_c v(0.0f, 0.0f, 1.0f);
                mAng ang = dActor_c::targetAngleY(pTarget, &p);
                mVec3_c q = mVec3_c::Zero;
                v.rotY(ang);
                v *= d;
                mVec3_c sum = *pTarget + v;
                q = sum;
                dFdBase_c::snapToUnitCenter(&q, &q);
                q.y = dBGCF::getGroundY(&q, FALSE);

                ok = false;
                if (std::fabs(pTarget->y - q.y) < 48.0f) {
                    dNpc::holeCheck_e holeCheck = dNpc::CHECK_HOLES;
                    if (fn_800F20D0(&q, ptrTo(dItem::Item((u16)0xFFF1)), NULL, 0x44, holeCheck, checkA)) {
                        ok = true;
                    }
                }
                if (ok) {
                    pPos->x = q.x;
                    pPos->z = q.z;
                    return TRUE;
                }
            }
        }
    }
    return FALSE;
}

BOOL dAcNpc_c::checkTargetAngle(mAng *pAngle, const mVec3_c *pTarget, const mAng *pRange) const {
    pAngle->mAngle = dActor_c::targetAngleY(&mPos, pTarget);
    long range = labs(pRange->mAngle);
    return labs((s16)(pAngle->mAngle - mAngle.y.mAngle)) < range;
}

u32 dAcNpc_c::selectFreeSide() {
    static const u32 ids[2] = {0xD7, 0xD6};
    static const f32 offX[2] = {-19.2f, 19.2f};

    u32 ret = 0xD6;
    dFdBase_c *fd = fn_80190C44(FD_ID_CURRENT);
    if (fd != NULL && fd->_24 != NULL) {
        u32 cnt = 0;
        for (int i = 0; i < 2; i++) {
            mVec3_c p = mPos;
            p.x += offX[i];
            if (!fn_800F3D20(&p)) {
                f32 chance = 100.0f / (cnt + 1);
                if (cM::rndF(100.0f) <= chance) {
                    ret = ids[i];
                }
                cnt++;
            }
        }
    }
    return ret;
}

BOOL dAcNpc_c::getPointedUnit(int *pUnitX, int *pUnitZ, const mAng *pAngle, int snapToCardinal, f32 range, f32 dist) {
    if (pUnitX == NULL || pUnitZ == NULL) {
        return FALSE;
    }
    if (fn_8018F438(0x11)) {
        return FALSE;
    }
    if (!fn_800FA748()) {
        return FALSE;
    }

    dPlayerActor_c *player = fn_800FBC7C(4);
    mVec3_c p = mVec3_c::Zero;
    player->getOffsetPos(&p, dist, snapToCardinal);

    const mVec3_c *firstPos;
    const mVec3_c *pos;
    bool found;
    BOOL ok;
    ok = TRUE;
    if (mPad::g_currentCore->getDpdValidFlag() && fn_800FA724()) {
        const dObjc::dpdHit_c *hit = dObjc::getDpdHit();
        int type = hit != NULL ? (int)hit->mType : 0;
        switch (type) {
        case (int)0x80000001:
            break;
        case (int)0x80020000: {
            firstPos = &hit->mPos;
            if (fn_800FFA50(firstPos, pAngle->mAngle, range)) {
                p = *firstPos;
            } else {
                ok = FALSE;
            }
            break;
        }
        case (int)0x80040000: {
            pos = &hit->mPos;
            void *ftr = NULL;
            found = fn_800FFA50(pos, pAngle->mAngle, range) != 0;
            if (found) {
                ftr = fn_800A900C(fn_800A9058(), &hit->mPos, 0);
            }
            if (!found) {
                ok = FALSE;
            }
            if (ftr != NULL) {
                p = *pos;
            } else {
                ok = FALSE;
            }
            break;
        }
        default:
            ok = FALSE;
            break;
        }
    }

    if (!ok) {
        return FALSE;
    }
    *pUnitX = (int)p.x >> 5;
    *pUnitZ = (int)p.z >> 5;
    return TRUE;
}

void dAcNpc_c::stopManpu() {
    mManpu.stopAll();
}

BOOL dAcNpc_c::checkWarpHome() {
    if (isLocalOwner()) {
        return FALSE;
    }
    if (mWarpDist == 0.0f) {
        return FALSE;
    }
    mVec3_c pos = mVec3_c::Zero;
    mAng ang = 0;
    if (!getDaubPos(&pos, &ang)) {
        return FALSE;
    }
    f32 dist = (mPos - pos).xzLen();
    if (dist <= mWarpDist) {
        return FALSE;
    }
    mPos = pos;
    mLastPos = pos;
    mAngle.y = ang;
    mAngle3D.y = ang;
    return TRUE;
}

