void dAcNpc_c::setGroundEffect(const char *sandName, const char *otherName, const mVec3_c *pPos, const mAng3_c *pAngle) {
    if (pPos == NULL) {
        pPos = &mPos;
    }
    if (pPos != NULL) {
        if (pAngle == NULL) {
            pAngle = &mAngle;
        }
        if (pAngle != NULL) {
            dBGCF::groundChk_c chk(pPos, 0, 0, 0);
            bool sand = false;
            bgAttr_e attr = static_cast<bgAttr_e>(chk.mAttr);
            int water = chk.mWater;
            if (attr == BG_ATTR_SAND || water == BG_WATER_SEA) {
                sand = true;
            }
            fn_80087790(sand ? sandName : otherName, pPos, pAngle, NULL);
        }
    }
}

int dAcNpc_c::preCreate() {
    if (dDemoActor_c::preCreate() == NOT_READY) {
        return NOT_READY;
    }

    mNpcItem = (u16)mParam;
    _DC = vtB8();
    setRecept(NULL);
    mTalk.init();
    mFrontChk.init();
    mManpu.init();
    const mMtx_c &identity = mMtx_c::Identity;
    mNodeMtx01 = identity;
    mNodeMtx12 = identity;
    mNodeMtx0B = identity;
    mNodeMtx0E = identity;
    mNodeMtx13 = identity;
    mNodeMtx04 = identity;
    mNodeMtx07 = identity;
    mIsActive = true;
    mCheckGround = true;
    mAudioObj.setMaxDist(l_moveParamRun.mSpeed);
    mDrawShadow = true;
    _1C3C = false;
    _1B70 = 4;
    mAcceptMoveReq = true;
    mWarpDist = 96.0f;
    mFootstep.init();
    setDemoFlag4();

    if (isNetSync() && mPermitState == 0) {
        if (fn_800F5550()) {
            dNpcPermit_c *permit = fn_800F54E0(&mNpcItem);
            if (permit != NULL) {
                permit->clear();
                fn_800F19C0(&mNpcItem);
                mPermitState = 1;
            }
        }
        if (mPermitState == 0) {
            mPermitState = 2;
        }
    }

    if (m_heap_p == NULL) {
        m_heap_p = mHeap::createFrmHeap(getHeapSize(), lbl_8074EABC, "dAcNpc_c::m_heap_p : NPCアクターヒープ", 0x20, mHeap::OPT_NONE);
        mAllocator.attach(m_heap_p, 0x20);
    }
    return SUCCEEDED;
}

int dAcNpc_c::create() {
    setDemoID(mNpcItem.mId & 0xFFF);
    if (mpRes != NULL && !mpRes->vt0C(this)) {
        return NOT_READY;
    }

    clothBase_c *cloth = getCloth();
    if (cloth != NULL && !cloth->vt14(this)) {
        return NOT_READY;
    }

    nw4r::g3d::ResFile mdlFile(getMdlResFile());
    nw4r::g3d::ResMdl mdl = mdlFile.GetResMdl(0);
    int anm = mAnmSet.mWaitAnm;
    mModel.create(mdl, anm, &mAllocator, 4, 0);
    int faceType = getFaceType();
    nw4r::g3d::ResFile texFile(getTexResFile());
    mFace.create(faceType, &mModel.mMdl, texFile, &mAllocator);
    int anmId = mModel.mAnm.mAnmId;
    mFace.setAnmTex(&mModel.mMdl, texFile, anmId, m3d::PLAYMODE_INHERIT);
    if (cloth != NULL) {
        cloth->vt18(mdl);
    }
    mLookAt.init(mModel.mMdl.getResMdl());
    mAction.init(this);
    mEar.init(nw4r::g3d::ResFile(getMdlResFile()).GetResMdl(0), getEarType());
    mObjc.set(this, 16.0f, 32.0f, 0x80000002, 0x8040007F, 0x80, mNpcItem.mId);
    return SUCCEEDED;
}

void dAcNpc_c::postCreate(MAIN_STATE_e state) {
    if (state == SUCCESS) {
        if (!fn_800DD960()) {
            mObjc.setTempWeight(0xFF);
        }
        mRecvDaubAsOwner = false;
        if (isNetSync()) {
            saveDaub();
            if (mPermitState == 2) {
                mRecvDaubAsOwner = true;
            }
            mPermitState = 3;
        }
    }
    dDemoActor_c::postCreate(state);
}

int dAcNpc_c::doDelete() {
    if (!mLoader.release()) {
        return NOT_READY;
    }
    if (m_heap_p != NULL) {
        mModel.remove();
        mFace.remove();
        mHeap::destroyFrmHeap(m_heap_p);
        m_heap_p = NULL;
    }
    vtBC();
    return SUCCEEDED;
}

int dAcNpc_c::execute() {
    mAudioObj.setPos(&mPos);
    if (!isLocalOwner() || mRecvDaubAsOwner) {
        recvDaub();
    }
    checkWarpHome();
    mAction.calcMove(this);

    if (mIsActive) {
        mPos += *mObjc.getPush();
        if (getSpeedF() != 0.0f && mObjc.mHitType != 0) {
            if (mPushTimer < 0xFFFFFFFF) {
                mPushTimer++;
            }
        } else {
            mPushTimer = 0;
        }
    } else {
        mPushTimer = 0;
    }

    mFrontChk.clear();
    mFrontChk.calc(this);
    vtB0();

    if (!isLocalOwner() && mAcceptMoveReq) {
        u32 type = 0x15;
        u32 sub = 0;
        action_c *action = &mAction;
        if (getDaubState(&type, &sub)) {
            if (sub == 0) {
                if (action->mActionId != 0x13) {
                    action->requestMoveDest(1);
                }
                action->setGait(type);
            } else {
                switch ((int)type) {
                case 1:
                case 2: {
                    mVec3_c from = mVec3_c::Zero;
                    mVec3_c to = mVec3_c::Zero;
                    u16 angle = 0;
                    f32 speed = 0.0f;
                    if (getDaubMove(&from, &to, &angle, &speed)) {
                        if ((int)type != action->mActionId || from != action->mTarget || to != action->mGoal) {
                            if ((int)type == 1) {
                                action->requestWalk(2, from, l_walkTurnSpeed, 0, l_moveParamWalk, 1.0f, speed);
                            } else {
                                action->requestRun(2, from, l_runTurnSpeed, 0, l_moveParamRun, 2.0f, speed);
                            }
                        }
                    }
                    break;
                }
                case 3: {
                    mAng a1 = 0;
                    mAng a2 = 0;
                    f32 f = 0.0f;
                    if (getDaubTalk((u16 *)&a1, (u16 *)&a2, &f)) {
                        if ((int)type != action->mActionId || a1.mAngle != action->mTargetAngle.mAngle) {
                            action->requestTurn(2, a1, a2, 0, f);
                        }
                    }
                    break;
                }
                case 9: {
                    u32 anmId = 0x1BC;
                    u8 playMode = 4;
                    f32 frame = 0.0f;
                    f32 morph = 0.0f;
                    if (getDaubAct(&anmId, &playMode, &frame, &morph)) {
                        if ((int)type != action->mActionId || (int)anmId != getModel()->mAnm.mAnmId) {
                            action->requestAnm(2, anmId, morph, frame, playMode, 0);
                        }
                    }
                    break;
                }
                }
            }
        }
    }

    mTalk.execute(this);
    mAction.calc(this);

    model_c *model = getModel();
    u32 anmId = getModel()->mAnm.mAnmId;
    mManpu.execute(&mNodeMtx12, anmId, &mAngle.y, &mAudioObj, model->mAnm.getFrame());

    if (isInUse(NULL)) {
        if (fn_800DD960()) {
            mObjc.setTempWeight(0xFF);
        }
    } else if (mObjc.isTempWeight() && fn_800DD960()) {
        mObjc.resetTempWeight();
    }

    if (mIsActive) {
        mObjc.regist();
        if (mCheckGround) {
            if (fn_800DD960()) {
                mPos.y -= 1.0f;
                mAcch.check(13.0f, &mPos, &mLastPos, mAngle.y, (int)this, 0x217, TRUE);
            } else {
                const mVec3_c *goal = &mAction.mGoal;
                if (getSpeedF() != 0.0f && *goal != mVec3_c::Zero) {
                    mPos.y = fn_80100194(goal, &mPos, &mLastPos);
                } else {
                    mPos.y = dBGCF::getGroundY(&mPos, FALSE);
                }
            }
        }
    }

    mLookAt.execute(this);
    getModel()->play();
    mFace.execute(this);
    getModel()->calc(this);
    mAction.calcAfter(this);
    mFootstep.calc(this);
    if (getTool() != NULL) {
        getTool()->execute(this);
    }
    if (getCloth() != NULL) {
        getCloth()->vt20(this);
    }

    mRecvDaubAsOwner = false;
    if (isNetSync()) {
        if (!isLocalOwner()) {
            mRecvDaubAsOwner = true;
        }
        saveDaub();
    }
    return SUCCEEDED;
}

int dAcNpc_c::draw() {
    if (!mIsActive) {
        return SUCCEEDED;
    }
    if (!mViewArea.isOutside(&mPos)) {
        getModel()->entry();
        if (getTool() != NULL) {
            getTool()->draw();
        }
        if (mDrawShadow) {
            f32 size = mShadowSize;
            if (size > 0.0f) {
                mVec3_c pos = getBodyPos();
                pos.y = dBGCF::getGroundY(&pos, FALSE);
                mAng ang = 0;
                f32 b = _1B68;
                f32 a = _1B64;
                fn_801C8518(&pos, 0, &ang, a, b, size, 0.0f, 1.0f);
            }
        }
    }
    return SUCCEEDED;
}

