int dAcNpc_c::demoHook64(mVec3_c *pos) {
    if (pos != NULL) {
        *pos = getNode0EPos();
        return TRUE;
    }
    return FALSE;
}

// ---- dAcNpc_c::texAnm_c (800167D0..80016CB4) ----

dAcNpc_c::texAnm_c::texAnm_c() {
    mTexId[1] = mTexId[0] = 0x1D3;
}

dAcNpc_c::texAnm_c::~texAnm_c() {}

bool dAcNpc_c::texAnm_c::isValid() const {
    return mFace.getType() < 13;
}

void dAcNpc_c::texAnm_c::createTex(int faceType, nw4r::g3d::ResMdl mdl, nw4r::g3d::ResFile file,
                                   mAllocator_c *allocator, size_t *pSize, long count) {
    if (!isValid()) {
        mFace.setType(faceType);
    }
    mFace.setTex(0, 0);
    nw4r::g3d::ResAnmTexPat pat = mFace.getResAnmTexPat(0);
    pat.Bind(file);
    m3d::anmTexPat_c::create(mdl, pat, allocator, pSize, count);
    mTexId[1] = mTexId[0] = 0x1D3;
}

BOOL dAcNpc_c::texAnm_c::setTexAnm(m3d::bmdl_c &mdl, nw4r::g3d::ResFile file, ulong idx, int texId,
                                   m3d::playMode_e playMode) {
    if (idx >= 2) {
        return FALSE;
    }
    if (!isValid()) {
        return FALSE;
    }
    if (playMode == m3d::PLAYMODE_INHERIT) {
        playMode = (m3d::playMode_e)fn_800B7E4C(texId);
    }
    releaseTexAnm(idx);
    mFace.setTex(idx, texId);
    nw4r::g3d::ResAnmTexPat pat = mFace.getResAnmTexPat(idx);
    pat.Bind(file);
    m3d::anmTexPat_c::setAnm(mdl, pat, idx, playMode);
    mdl.setAnm(*this);
    mTexId[idx] = texId;
    return TRUE;
}

BOOL dAcNpc_c::texAnm_c::releaseTexAnm(ulong idx) {
    if (idx >= 2) {
        return FALSE;
    }
    if (!isValid()) {
        return FALSE;
    }
    releaseAnm(idx);
    nw4r::g3d::ResAnmTexPat pat = mFace.getResAnmTexPat(idx);
    if (pat.IsValid()) {
        pat.Release();
    }
    mTexId[idx] = 0x1D3;
    return TRUE;
}

bool dAcNpc_c::texAnm_c::isTexAnmStop(ulong idx) const {
    if (!isValid()) {
        return false;
    }
    if (idx >= 2) {
        return false;
    }
    if (mTexId[idx] != 0x1D3 && m3d::anmTexPat_c::isStop(idx)) {
        return true;
    }
    return false;
}

m3d::playMode_e dAcNpc_c::texAnm_c::getTexPlayMode(ulong idx) const {
    if (!isValid()) {
        return (m3d::playMode_e)0;
    }
    if (idx >= 2) {
        return (m3d::playMode_e)0;
    }
    if (mTexId[idx] != 0x1D3) {
        return m3d::anmTexPat_c::getPlayMode(idx);
    }
    return (m3d::playMode_e)0;
}

void dAcNpc_c::texAnm_c::remove() {
    if (isValid()) {
        for (int i = 0; i < 2; i++) {
            nw4r::g3d::ResAnmTexPat pat = mFace.getResAnmTexPat(i);
            if (pat.IsValid()) {
                pat.Release();
            }
        }
        m3d::anmTexPat_c::remove();
    }
}

// ---- dAcNpc_c::chrPartAnm_c (80016CB4..80016F50) ----

dAcNpc_c::chrPartAnm_c::chrPartAnm_c() : mAnmId(0x1BC) {}

dAcNpc_c::chrPartAnm_c::~chrPartAnm_c() {}

BOOL dAcNpc_c::chrPartAnm_c::setPartAnm(m3d::mdlEx_c &mdl, int anmId, int partIdx, m3d::playMode_e playMode,
                                        f32 frame, f32 rate, f32 blend) {
    if (anmId >= 0x1BC) {
        return FALSE;
    }
    if (anmId == mAnmId) {
        setRate(rate);
        return TRUE;
    }
    if (playMode == m3d::PLAYMODE_INHERIT) {
        playMode = (m3d::playMode_e)dHmnAnm_c::getPlayMode(anmId);
    }
    releasePartAnm(mdl, partIdx, blend);
    m3d::anmChrPart_c::setAnm(mdl, dHmnAnm_c::getResAnmChr(anmId), playMode);
    setFrame(frame);
    setRate(rate);
    mdl.setPartAnm(partIdx, this, blend);
    mAnmId = anmId;
    return TRUE;
}

void dAcNpc_c::chrPartAnm_c::releasePartAnm(m3d::mdlEx_c &mdl, int partIdx, f32 blend) {
    if (mAnmId != 0x1BC) {
        mdl.removePartAnm(partIdx, blend);
        mAnmId = 0x1BC;
    }
}

void dAcNpc_c::chrPartAnm_c::setPartNode(m3d::mdlEx_c &mdl, u8 partIdx, ulong nodeId) const {
    if (mAnmId == 0x1BC) {
        return;
    }
    if (nodeId == (ulong)-1) {
        return;
    }
    mdl.setPartNode(partIdx, nodeId);
}

void dAcNpc_c::chrPartAnm_c::createAnm(nw4r::g3d::ResMdl mdl, int anmId, mAllocator_c *allocator) {
    if (anmId < 0x1BC) {
        m3d::anmChr_c::create(mdl, dHmnAnm_c::getResAnmChr(anmId), allocator, NULL);
    }
}

void dAcNpc_c::chrPartAnm_c::remove() {
    m3d::banm_c::remove();
}

// ---- dAcNpc_c::face_c (80016F50..80017F84) ----

dAcNpc_c::face_c::face_c() {
    mSavedMouthTex = 0x1D3;
    mSavedMouthMode = m3d::PLAYMODE_INHERIT;
    mTalk = 0;
    mDisable = 0;
}

dAcNpc_c::face_c::~face_c() {}

bool dAcNpc_c::face_c::hasMouthMat(nw4r::g3d::ResMdl mdl) {
    const char *name = model_c::getMatName(1);
    if (name == NULL) {
        return false;
    }
    return mdl.GetResMat(name).IsValid();
}

bool dAcNpc_c::face_c::hasMouthMat(m3d::bmdl_c *mdl) {
    nw4r::g3d::ResMdl resMdl = mdl->getResMdl();
    if (resMdl.IsValid()) {
        return hasMouthMat(resMdl);
    }
    return false;
}

bool dAcNpc_c::face_c::hasEyeMat(nw4r::g3d::ResMdl mdl) {
    const char *name = model_c::getMatName(0);
    if (name == NULL) {
        return false;
    }
    return mdl.GetResMat(name).IsValid();
}

bool dAcNpc_c::face_c::hasEyeMat(m3d::bmdl_c *mdl) {
    nw4r::g3d::ResMdl resMdl = mdl->getResMdl();
    if (resMdl.IsValid()) {
        return hasEyeMat(resMdl);
    }
    return false;
}

bool dAcNpc_c::face_c::isValid() const {
    return mTexAnm.isValid();
}

bool dAcNpc_c::face_c::isTalkMouthTex(int texId) {
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            if (texId == l_80465A00[i][j]) {
                return true;
            }
        }
    }
    return false;
}

BOOL dAcNpc_c::face_c::setTex(m3d::mdlEx_c *mdl, nw4r::g3d::ResFile file, int idx, int texId,
                              m3d::playMode_e playMode) {
    if (!isValid() || idx >= 2) {
        return FALSE;
    }
    if (mDisable) {
        return FALSE;
    }
    if (idx == 1 && !hasMouthMat(mdl)) {
        return TRUE;
    }
    if (idx == 0 && !hasEyeMat(mdl)) {
        return TRUE;
    }
    if (texId >= 0x1D3) {
        texId = idx != 0;
    }
    if (texId == mTexAnm.mTexId[idx]) {
        return TRUE;
    }
    if (idx == 1) {
        if (isTalkMouthTex(mTexAnm.mTexId[1])) {
            if (mTexAnm.isTexAnmStop(1)) {
                mTexAnm.setTexAnm(*mdl, file, idx, texId, playMode);
                if (!isTalkMouthTex(texId)) {
                    mSavedMouthTex = 0x1D3;
                    mSavedMouthMode = m3d::PLAYMODE_INHERIT;
                }
            } else if (!isTalkMouthTex(texId)) {
                mSavedMouthTex = texId;
                mSavedMouthMode = playMode;
            }
        } else {
            if (isTalkMouthTex(texId)) {
                mSavedMouthTex = mTexAnm.mTexId[1];
                mSavedMouthMode = mTexAnm.getTexPlayMode(1);
            } else {
                mSavedMouthTex = 0x1D3;
                mSavedMouthMode = m3d::PLAYMODE_INHERIT;
            }
            mTexAnm.setTexAnm(*mdl, file, idx, texId, playMode);
        }
    } else {
        mTexAnm.setTexAnm(*mdl, file, idx, texId, playMode);
    }
    return TRUE;
}

BOOL dAcNpc_c::face_c::setAnmTex(m3d::mdlEx_c *mdl, nw4r::g3d::ResFile file, int anmId, m3d::playMode_e playMode) {
    int eyeTex = fn_800B7890(anmId);
    if (setTex(mdl, file, 0, eyeTex, playMode)) {
        int mouthTex = fn_800B78B4(anmId);
        return setTex(mdl, file, 1, mouthTex, playMode);
    }
    return FALSE;
}

BOOL dAcNpc_c::face_c::setAnmTex(dAcNpc_c *npc, int anmId, m3d::playMode_e playMode) {
    nw4r::g3d::ResFile file(npc->getTexResFile());
    return setAnmTex(&npc->getModel()->mMdl, file, anmId, playMode);
}

BOOL dAcNpc_c::face_c::releaseTex(m3d::mdlEx_c *mdl, int idx) {
    if (mDisable) {
        return FALSE;
    }
    if (idx == 1 && !hasMouthMat(mdl)) {
        return TRUE;
    }
    if (idx == 0 && !hasEyeMat(mdl)) {
        return TRUE;
    }
    if (mTexAnm.releaseTexAnm(idx)) {
        if (idx == 1) {
            mSavedMouthTex = 0x1D3;
            mSavedMouthMode = m3d::PLAYMODE_INHERIT;
        }
        return TRUE;
    }
    return FALSE;
}

BOOL dAcNpc_c::face_c::releaseTex(dAcNpc_c *npc, int idx) {
    return releaseTex(&npc->getModel()->mMdl, idx);
}

int dAcNpc_c::face_c::getRandomIdx() {
    return ((int)cM::rndF(4.0f) & 1) ^ 1;
}

int dAcNpc_c::face_c::getMouthKind(dAcNpc_c *npc) {
    return fn_800B7E48(fn_800B78B4(npc->getModel()->mAnm.mAnmId));
}

int dAcNpc_c::face_c::getTalkMouthTex(dAcNpc_c *npc) {
    u32 rnd = getRandomIdx();
    u32 kind = getMouthKind(npc);
    if (rnd < 2 && kind < 2) {
        return l_80465A00[rnd][kind];
    }
    return 0x1D3;
}

BOOL dAcNpc_c::face_c::setTalkMouthTex(dAcNpc_c *npc) {
    u32 tex = getTalkMouthTex(npc);
    if (tex < 0x1D3) {
        nw4r::g3d::ResFile file(npc->getTexResFile());
        return setTex(&npc->getModel()->mMdl, file, 1, tex, m3d::PLAYMODE_INHERIT);
    }
    return FALSE;
}

BOOL dAcNpc_c::face_c::restoreMouthTex(m3d::mdlEx_c *mdl, nw4r::g3d::ResFile file) {
    if (mSavedMouthTex != 0x1D3) {
        return setTex(mdl, file, 1, mSavedMouthTex, mSavedMouthMode);
    }
    return FALSE;
}

int dAcNpc_c::face_c::getTalkMouthAnm() {
    return l_talkMouthAnm[getRandomIdx()];
}

BOOL dAcNpc_c::face_c::setTalkMouthAnm(m3d::mdlEx_c *mdl) {
    if (mDisable) {
        return FALSE;
    }
    if (hasMouthMat(mdl)) {
        return TRUE;
    }
    nw4r::g3d::ResNode node = mdl->getResMdl().GetResNode(l_mouthNodeName);
    if (!node.IsValid()) {
        return FALSE;
    }
    ulong nodeId = node.GetID();
    if (!mMouthAnm.setPartAnm(*mdl, getTalkMouthAnm(), 3, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, 0.0f)) {
        return FALSE;
    }
    mMouthAnm.setPartNode(*mdl, 3, nodeId);
    return TRUE;
}

BOOL dAcNpc_c::face_c::stopTalkMouthAnm(m3d::mdlEx_c *mdl) {
    if (mDisable) {
        return FALSE;
    }
    mMouthAnm.releasePartAnm(*mdl, 3, 0.0f);
    return TRUE;
}

bool dAcNpc_c::face_c::isTalkMouthAnm(int anmId) {
    for (int i = 0; i < 2; i++) {
        if (anmId == l_talkMouthAnm[i]) {
            return true;
        }
    }
    return false;
}

void dAcNpc_c::face_c::startTalkMouth(dAcNpc_c *npc) {
    m3d::mdlEx_c *mdl = &npc->getModel()->mMdl;
    if (hasMouthMat(mdl)) {
        setTalkMouthTex(npc);
    } else {
        setTalkMouthAnm(mdl);
    }
}

void dAcNpc_c::face_c::endTalkMouth(dAcNpc_c *npc) {
    m3d::mdlEx_c *mdl = &npc->getModel()->mMdl;
    if (hasMouthMat(mdl)) {
        restoreMouthTex(mdl, nw4r::g3d::ResFile(npc->getTexResFile()));
    } else {
        stopTalkMouthAnm(mdl);
    }
}

bool dAcNpc_c::face_c::isTalkMouth(dAcNpc_c *npc) const {
    if (hasMouthMat(&npc->getModel()->mMdl)) {
        if (isTalkMouthTex(mTexAnm.mTexId[1])) {
            return true;
        }
    } else if (isTalkMouthAnm(mMouthAnm.mAnmId)) {
        return true;
    }
    return false;
}

bool dAcNpc_c::face_c::isTalkMouthStop(dAcNpc_c *npc) const {
    if (hasMouthMat(&npc->getModel()->mMdl)) {
        if (mTexAnm.mTexId[1] != 0x1D3) {
            return mTexAnm.isTexAnmStop(1);
        }
    } else if (mMouthAnm.mAnmId != 0x1BC) {
        return mMouthAnm.isStop();
    }
    return false;
}

void dAcNpc_c::face_c::setTalk() {
    mTalk = 1;
}

void dAcNpc_c::face_c::clearTalk() {
    mTalk = 0;
}

bool dAcNpc_c::face_c::isTalk() const {
    return mTalk != 0;
}

void dAcNpc_c::face_c::create(int faceType, m3d::mdlEx_c *mdl, nw4r::g3d::ResFile file, mAllocator_c *allocator) {
    if (isValid()) {
        return;
    }
    nw4r::g3d::ResMdl resMdl = mdl->getResMdl();
    int count = 0;
    const char *eyeMat = model_c::getMatName(0);
    if (eyeMat != NULL) {
        if (resMdl.GetResMat(eyeMat).IsValid()) {
            count = 1;
        }
    }
    if (hasMouthMat(resMdl)) {
        count++;
    } else {
        mMouthAnm.createAnm(resMdl, 0xC1, allocator);
    }
    if (count > 0) {
        mTexAnm.createTex(faceType, resMdl, file, allocator, NULL, count);
    }
    mTexAnm.mFace.resetBlink();
    mDisable = 0;
}

void dAcNpc_c::face_c::remove() {
    mDisable = 0;
    mMouthAnm.remove();
    if (isValid()) {
        mTexAnm.remove();
    }
}

void dAcNpc_c::face_c::reset(m3d::mdlEx_c *mdl) {
    mDisable = 0;
    stopTalkMouthAnm(mdl);
    if (isValid()) {
        releaseTex(mdl, 0);
        releaseTex(mdl, 1);
    }
    mTexAnm.mFace.resetBlink();
    mSavedMouthTex = 0x1D3;
    mSavedMouthMode = m3d::PLAYMODE_INHERIT;
    clearTalk();
}

void dAcNpc_c::face_c::execute(dAcNpc_c *npc) {
    if (!isValid()) {
        return;
    }
    if (mDisable) {
        return;
    }
    dHmnFaceAnmMng_c &face = mTexAnm.mFace;
    if (mTexAnm.mTexId[0] == 0) {
        // the default eyes: blink
        bool restart = false;
        if (face.calcBlink() && (mTexAnm.isTexAnmStop(0) || mTexAnm.checkFrame(0.0f, 0))) {
            restart = true;
        }
        if (restart) {
            mTexAnm.setFrame(0.0f, 0);
        }
        if (restart || !(mTexAnm.isTexAnmStop(0) || mTexAnm.checkFrame(0.0f, 0))) {
            mTexAnm.play(0);
        }
    } else if (mTexAnm.mTexId[0] != 0x1D3) {
        mTexAnm.play(0);
    }

    if (getMouthKind(npc) < 2) {
        if (isTalk()) {
            if (!isTalkMouth(npc) || isTalkMouthStop(npc)) {
                startTalkMouth(npc);
            }
        } else if (isTalkMouth(npc) && isTalkMouthStop(npc)) {
            endTalkMouth(npc);
        }
    } else if (isTalkMouth(npc)) {
        endTalkMouth(npc);
    }

    int mouthTex = mTexAnm.mTexId[1];
    if (hasMouthMat(&npc->getModel()->mMdl)) {
        if (mouthTex != 0x1D3) {
            if (mTexAnm.mFace.getResAnmTexPat(1).IsValid()) {
                mTexAnm.play(1);
            }
        }
    }
}

