// ---- dAcNpc_c::objc_c (80017FDC..800182A0) ----

dAcNpc_c::objc_c::objc_c() {
    mDefWeight = 0xF0;
    mTempWeight = 0xF0;
    mWeightFlag = 0;
}

dAcNpc_c::objc_c::~objc_c() {}

void dAcNpc_c::objc_c::onWeightFlag(ulong bit) {
    if (bit < 2) {
        mWeightFlag |= (1 << bit);
    }
}

void dAcNpc_c::objc_c::offWeightFlag(ulong bit) {
    if (bit < 2) {
        mWeightFlag &= ~(1 << bit);
    }
}

bool dAcNpc_c::objc_c::isWeightFlag(ulong bit) const {
    if (bit < 2 && ((mWeightFlag >> bit) & 1)) {
        return true;
    }
    return false;
}

bool dAcNpc_c::objc_c::isTempWeight() const {
    return isWeightFlag(0);
}

bool dAcNpc_c::objc_c::isFixWeight() const {
    return isWeightFlag(1);
}

u8 dAcNpc_c::objc_c::convWeight(u8 weight) {
    if (weight == 0x80) {
        weight = 0xF0;
    }
    return weight;
}

void dAcNpc_c::objc_c::setDefWeight(u8 weight) {
    u8 w = convWeight(weight);
    mDefWeight = w;
    if (mWeightFlag == 0) {
        mWeight = w;
    }
}

void dAcNpc_c::objc_c::setTempWeight(u8 weight) {
    mTempWeight = convWeight(weight);
    if (!isWeightFlag(1)) {
        mWeight = mTempWeight;
    }
    onWeightFlag(0);
}

void dAcNpc_c::objc_c::resetTempWeight() {
    if (isWeightFlag(0)) {
        if (!isWeightFlag(1)) {
            mWeight = mDefWeight;
        }
        offWeightFlag(0);
    }
}

void dAcNpc_c::objc_c::setFixWeight(u8 weight) {
    mWeight = convWeight(weight);
    onWeightFlag(1);
}

void dAcNpc_c::objc_c::resetFixWeight() {
    if (isWeightFlag(1)) {
        if (isWeightFlag(0)) {
            mWeight = mTempWeight;
        } else {
            mWeight = mDefWeight;
        }
        offWeightFlag(1);
    }
}

// ---- dAcNpc_c::anm_c (800182A0..80018500) ----

dAcNpc_c::anm_c::anm_c() : mAnmId(0x1BC) {}

dAcNpc_c::anm_c::~anm_c() {}

BOOL dAcNpc_c::anm_c::changeAnm(m3d::mdlEx_c &mdl, mdlCallback_c *callback, int anmId, m3d::playMode_e playMode,
                                BOOL force, f32 frame, f32 rate, f32 blend) {
    if (anmId >= 0x1BC) {
        return FALSE;
    }
    if (playMode == m3d::PLAYMODE_INHERIT) {
        playMode = (m3d::playMode_e)dHmnAnm_c::getPlayMode(anmId);
    }
    if (!force && anmId == mAnmId && playMode == mPlayMode) {
        setRate(rate);
        return TRUE;
    }
    m3d::anmChr_c::setAnm(mdl, dHmnAnm_c::getResAnmChr(anmId), playMode);
    setRate(rate);
    mdl.setAnm(*this, blend);
    if (playMode == m3d::REVERSE_LOOP || playMode == m3d::REVERSE_ONCE) {
        frame = mFrameMax - 1.0f - frame;
    }
    setFrame(frame);
    mAnmId = anmId;
    callback->mAnmId = anmId;
    return TRUE;
}

void dAcNpc_c::anm_c::createAnm(nw4r::g3d::ResMdl mdl, int anmId, mAllocator_c *allocator) {
    if (anmId < 0x1BC) {
        m3d::anmChr_c::create(mdl, dHmnAnm_c::getResAnmChr(anmId), allocator, NULL);
    }
}

void dAcNpc_c::anm_c::remove() {
    m3d::banm_c::remove();
}

// ---- dAcNpc_c::model_c (80018500..80018E64) ----

dAcNpc_c::model_c::model_c(dAcNpc_c *npc) : mCallback(npc) {
    mCreated = 0;
    _EC = 1.0f;
    mPlay = 1;
}

dAcNpc_c::model_c::~model_c() {}

const char *dAcNpc_c::model_c::getMatName(ulong idx) {
    const char *name = l_faceMatName[idx];
    if (idx < 2) {
        return name;
    }
    return NULL;
}

const char *dAcNpc_c::model_c::getTexName(ulong idx) {
    const char *name = l_faceTexName[idx];
    if (idx < 2) {
        return name;
    }
    return NULL;
}

BOOL dAcNpc_c::model_c::create(nw4r::g3d::ResMdl mdl, int anmId, mAllocator_c *allocator, ulong anmNum,
                               ulong bufferOption) {
    if (mCreated) {
        return TRUE;
    }
    mMdl.create(mdl, allocator, anmNum, bufferOption, 1, NULL);
    mMdl.setCallback(&mCallback);
    mAnm.createAnm(mdl, anmId, allocator);
    mMdl.setAnm(mAnm);
    mRarmAnm.createAnm(mdl, 0x14, allocator);
    mLarmAnm.createAnm(mdl, 0x60, allocator);
    nw4r::g3d::ResNode node = mdl.GetResNode(l_rarmNodeName);
    if (node.IsValid()) {
        mRarmNodeId = node.GetID();
    } else {
        mRarmNodeId = -1;
    }
    node = mdl.GetResNode(l_larmNodeName);
    if (node.IsValid()) {
        mLarmNodeId = node.GetID();
    } else {
        mLarmNodeId = -1;
    }
    mCreated = 1;
    return TRUE;
}

void dAcNpc_c::model_c::remove() {
    if (mCreated) {
        mMdl.getResMdl().Release();
    }
    mMdl.remove();
    mAnm.remove();
    mRarmAnm.remove();
    mLarmAnm.remove();
    mCreated = 0;
}

void dAcNpc_c::model_c::play() {
    if (mPlay) {
        mMdl.play();
    } else {
        mMdl.calcBlend();
    }
}

void dAcNpc_c::model_c::calc(dAcNpc_c *npc) {
    mMtx_c mtx;
    npc->makeMtx(&mtx);
    mtx.XrotM(npc->mAngle.x);
    mMdl.setLocalMtx(&mtx);
    mMdl.calc(false);
}

BOOL dAcNpc_c::model_c::setAnm(int anmId, m3d::playMode_e playMode, f32 frame, f32 rate, f32 blend, BOOL force) {
    mPlay = 1;
    return mAnm.changeAnm(mMdl, &mCallback, anmId, playMode, force, frame, rate, blend);
}

BOOL dAcNpc_c::model_c::setRarmAnm(int anmId, m3d::playMode_e playMode, f32 frame, f32 rate, f32 blend) {
    if (mRarmNodeId == (ulong)-1) {
        return FALSE;
    }
    if (!mRarmAnm.setPartAnm(mMdl, anmId, 1, playMode, frame, rate, blend)) {
        return FALSE;
    }
    mRarmAnm.setPartNode(mMdl, 1, mRarmNodeId);
    return TRUE;
}

void dAcNpc_c::model_c::stopRarmAnm(f32 blend) {
    mRarmAnm.releasePartAnm(mMdl, 1, blend);
    if (mLarmAnm.mAnmId != 0x1BC && mRarmNodeId != (ulong)-1) {
        mLarmAnm.setPartNode(mMdl, 2, mRarmNodeId);
    }
}

BOOL dAcNpc_c::model_c::setLarmAnm(int anmId, m3d::playMode_e playMode, BOOL both, f32 frame, f32 rate, f32 blend) {
    if (mRarmNodeId == (ulong)-1 || mLarmNodeId == (ulong)-1) {
        return FALSE;
    }
    if (!mLarmAnm.setPartAnm(mMdl, anmId, 2, playMode, frame, rate, blend)) {
        return FALSE;
    }
    mLarmAnm.setPartNode(mMdl, 2, mLarmNodeId);
    if (mRarmAnm.mAnmId == 0x1BC && both) {
        mLarmAnm.setPartNode(mMdl, 2, mRarmNodeId);
    }
    return TRUE;
}

void dAcNpc_c::model_c::stopLarmAnm(f32 blend) {
    mLarmAnm.releasePartAnm(mMdl, 2, blend);
    if (mRarmAnm.mAnmId != 0x1BC && mRarmNodeId != (ulong)-1) {
        mRarmAnm.setPartNode(mMdl, 1, mRarmNodeId);
    }
}

void dAcNpc_c::model_c::entry() {
    mMdl.entry();
}

BOOL dAcNpc_c::model_c::setFaceTex(dAcNpc_c *npc, ulong idx, const char *texName) {
    if (npc == NULL || texName == NULL) {
        return FALSE;
    }
    const char *matName = getMatName(idx);
    if (matName == NULL) {
        return FALSE;
    }
    const char *slotName = getTexName(idx);
    if (slotName == NULL) {
        return FALSE;
    }
    nw4r::g3d::ResFile file(npc->getTexResFile());
    if (!file.IsValid()) {
        return FALSE;
    }
    nw4r::g3d::ResMdl resMdl = mMdl.getResMdl();
    nw4r::g3d::ResMat mat = resMdl.GetResMat(matName);
    if (!mat.IsValid()) {
        return FALSE;
    }
    nw4r::g3d::ResTex tex = file.GetResTex(texName);
    if (!tex.IsValid()) {
        return FALSE;
    }
    npc->mFace.releaseTex(npc, idx);
    mat.ReleaseTexByName(slotName, strlen(slotName));
    return mat.BindTexByName(tex, slotName) != 0;
}

void dAcNpc_c::model_c::setFrame(f32 frame, BOOL play) {
    mAnm.setFrame(frame);
    if (play) {
        mPlay = 1;
    } else {
        mPlay = 0;
    }
}

BOOL dAcNpc_c::model_c::copyAnm(model_c *dst) const {
    if (!mCreated || !dst->mCreated) {
        return FALSE;
    }
    if (this == dst) {
        return FALSE;
    }
    int anmId = mAnm.mAnmId;
    if (anmId == 0x1BC) {
        return FALSE;
    }
    // the target calls getFrame() / getRate() once with the results unused (unused locals)
    f32 frame = mAnm.getFrame();
    f32 rate = mAnm.getRate();
    m3d::playMode_e mode = (m3d::playMode_e)mAnm.mPlayMode;
    dst->setAnm(anmId, mode, mAnm.getFrame(), mAnm.getRate(), 0.0f, FALSE);

    int rarmId = mRarmAnm.mAnmId;
    if (rarmId != 0x1BC) {
        u8 rarmMode = mRarmAnm.mPlayMode;
        dst->setRarmAnm(rarmId, (m3d::playMode_e)rarmMode, mRarmAnm.getFrame(), mRarmAnm.getRate(), 0.0f);
    } else {
        dst->stopRarmAnm(0.0f);
    }

    int larmId = mLarmAnm.mAnmId;
    if (larmId != 0x1BC) {
        BOOL both = TRUE;
        if (larmId == 0x6B) {
            both = FALSE;
        }
        u8 larmMode = mLarmAnm.mPlayMode;
        dst->setLarmAnm(larmId, (m3d::playMode_e)larmMode, both, mLarmAnm.getFrame(), mLarmAnm.getRate(),
                        0.0f);
    } else {
        dst->stopLarmAnm(0.0f);
    }

    dst->_EC = _EC;
    dst->mPlay = mPlay;
    return TRUE;
}

