// ---- manpu_c (8001A9E8..8001B014) ----
dAcNpc_c::manpu_c::manpu_c() {
    mpData = NULL;
    mState = STATE_NONE;
    mAnmId = 0x1BC;
}

dAcNpc_c::manpu_c::~manpu_c() {}

void dAcNpc_c::manpu_c::reset() {
    for (u32 i = 0; i < 4; i++) {
        mEf[i].clear();
    }
    mpData = NULL;
    mState = STATE_NONE;
    mAnmId = 0x1BC;
    mOfs = mVec3_c::Zero;
    mOfsL = mVec3_c::Zero;
    mOfsR = mVec3_c::Zero;
}

BOOL dAcNpc_c::manpu_c::isActive() const {
    if (mState < STATE_NONE && mpData != NULL) {
        return TRUE;
    }
    return FALSE;
}

