int dAcNpc_c::manpu_c::start13(const mMtx_c *mtx, int anmId, u8 frame, const mAng *angY, dAudioObjNpc_c *audio, const mVec3_c *pos, const mVec3_c *v1, const mVec3_c *v2) {
    if (anmId != mAnmId) {
        return FALSE;
    }
    if (frame != 0) {
        return FALSE;
    }
    mEf[0].set(0x0C);
    if (!mEf[0].callCreate(mtx, pos, v1, v2)) {
        return FALSE;
    }
    holdSound(audio, 0x18DD);
    mState = STATE_EXEC;
    return TRUE;
}

int dAcNpc_c::manpu_c::exec13(const mMtx_c *mtx, int anmId, u8 frame, const mAng *angY, dAudioObjNpc_c *audio, const mVec3_c *pos, const mVec3_c *v1, const mVec3_c *v2) {
    BOOL r = mEf[0].callExecute(mtx, pos, v1, v2);
    holdSound(audio, 0x18DD);
    return r;
}

int dAcNpc_c::manpu_c::startHa(const mMtx_c *mtx, int anmId, u8 frame, const mAng *angY, dAudioObjNpc_c *audio, const mVec3_c *pos, const mVec3_c *v1, const mVec3_c *v2, u32 se) {
    if (anmId != mAnmId) {
        return FALSE;
    }
    if (frame != 0) {
        return FALSE;
    }
    bool right = angY->mAngle > 0 || angY->mAngle == -0x8000;
    int kind = 0x18;
    if (right) {
        kind = 0x19;
    }
    mVec3_c trans(mtx->m[0][3], mtx->m[1][3], mtx->m[2][3]);
    mMtx_c transMtx;
    transMtx.trans(trans);
    mEf[0].set(kind);
    BOOL r = mEf[0].callCreate(&transMtx, pos, v1, v2);
    if (r) {
        mState = STATE_EXEC;
        startSound(audio, se);
    }
    return r;
}

