int dAcNpc_c::manpu_c::startHyu(const mMtx_c *mtx, int anmId, u8 frame, const mAng *angY, dAudioObjNpc_c *audio, const mVec3_c *pos, const mVec3_c *v1, const mVec3_c *v2, u32 se) {
    static const char nameL[] = "afm_mnp_hyu_L";
    static const char leafNameL[] = "afm_mnp_hyu_leaf_L";
    static const char nameR[] = "afm_mnp_hyu_R";
    static const char leafNameR[] = "afm_mnp_hyu_leaf_R";
    const char *name = nameL;
    const char *leafName = leafNameL;
    if (angY->mAngle > 0 || angY->mAngle == -0x8000) {
        name = nameR;
        leafName = leafNameR;
    }
    BOOL r = createOneShot(mtx, anmId, frame, angY, name, 0);
    if (r) {
        r = createOneShot(mtx, anmId, frame, angY, leafName, 0);
    }
    startSound(audio, se);
    return r;
}

