void dAcNpc_c::action_c::setTargetPos(const mVec3_c &pos) {
    actionPrm_c *work = getWorkPrm();
    if (work->mTarget == work->mGoal) {
        setGoalPos(pos);
    }
    work->mTarget = pos;
    if (hasRequest()) {
        getReqPrm()->mTarget = pos;
    }
}

void dAcNpc_c::action_c::setGoalPos(const mVec3_c &pos) {
    getWorkPrm()->mGoal = pos;
    if (hasRequest()) {
        getReqPrm()->mGoal = pos;
    }
}

void dAcNpc_c::action_c::setTargetAngle(const mAng &angle) {
    getWorkPrm()->mAngle = angle;
    if (hasRequest()) {
        getReqPrm()->mAngle = angle;
    }
}

void dAcNpc_c::action_c::resetGoal() {
    move_c::resetGoal();
    setGoalPos(mTarget);
}

