// 8001FB18
int dAcNpc_c::action_c::initWait(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    reset();
    setAngle(npc->mAngle.y);
    npc->setAnm(npc->mAnmSet.mWaitAnm, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE);
    if (npc->isLocalOwner()) {
        dNpcDaub_c *daub = fn_800EFD04(&npc->mNpcItem.mId);
        if (daub != NULL) {
            daub->set19(mActionId, mCurPrio);
        }
    }
    mCanChange = FALSE;
    return 1;
}

// 8001FC0C
void dAcNpc_c::action_c::execWait(dAcNpc_c *npc) {
    mCanChange = TRUE;
}

// 8001FC18
int dAcNpc_c::action_c::initWalk(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    reset();
    setTarget(prm->mTarget);
    setGoal(prm->mGoal);
    setAngle(npc->mAngle.y);
    setTurnSpeed(prm->mTurnSpeed);
    setParam(prm->mMoveParam);
    mTurnMode = prm->mTurnMode;
    mArriveDist = prm->mArriveDist;
    npc->setAnm(npc->mAnmSet.mWalkAnm, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE);
    mCanChange = FALSE;
    if (npc->isLocalOwner()) {
        dNpcDaub_c *daub = fn_800EFD04(&npc->mNpcItem.mId);
        if (daub != NULL) {
            daub->set19(mActionId, mCurPrio);
            daub->setMove(&prm->mTarget, &prm->mGoal, (const u16 *)&prm->mTurnSpeed, prm->mMorph);
        }
    }
    return 1;
}

// 8001FD64
void dAcNpc_c::action_c::execWalk(dAcNpc_c *npc) {
    actionPrm_c *prm = getWorkPrm();
    setTarget(prm->mTarget);
    setGoal(prm->mGoal);
    setTurnSpeed(prm->mTurnSpeed);
    calcTargetAngle(npc);
    if (isArrived(npc, FALSE)) {
        if (isDetour()) {
            resetGoal();
        } else {
            mCanChange = TRUE;
        }
    }
}

