// 80020008
int dAcNpc_c::action_c::initTurn(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    reset();
    setAngle(prm->mAngle);
    setTurnSpeed(prm->mTurnSpeed);
    mTurnMode = prm->mTurnMode;
    npc->mAngle3D.y = npc->mAngle.y;
    if (npc->mAngle.y.mAngle != mTargetAngle.mAngle) {
        npc->setAnm(npc->mAnmSet.mWalkAnm, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE);
        mCanChange = FALSE;
    } else {
        npc->setAnm(npc->mAnmSet.mWaitAnm, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE);
        mCanChange = TRUE;
    }
    if (npc->isLocalOwner()) {
        dNpcDaub_c *daub = fn_800EFD04(&npc->mNpcItem.mId);
        if (daub != NULL) {
            daub->set19(mActionId, mCurPrio);
            daub->setTalk((const u16 *)&prm->mAngle, (const u16 *)&prm->mTurnSpeed, prm->mMorph);
        }
    }
    return 1;
}

// 800201A8
void dAcNpc_c::action_c::execTurn(dAcNpc_c *npc) {
    actionPrm_c *work = getWorkPrm();
    actionPrm_c *prm = getPrm();
    setAngle(work->mAngle);
    setTurnSpeed(work->mTurnSpeed);
    if (!mCanChange && npc->mAngle.y.mAngle == mTargetAngle.mAngle) {
        npc->setAnm(npc->mAnmSet.mWaitAnm, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE);
        mCanChange = TRUE;
    }
}

