// ---- dAcNpc_c::action_c: emotion, anm, catch ----

// 80020B50
int dAcNpc_c::action_c::initEmotion(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    int emotion = prm->mEmotion;
    reset();
    setAngle(npc->mAngle.y);
    if (emotion > 83) {
        emotion = 0;
    }
    mEmotion = emotion;
    const emotionData_s *data = getEmotionData(emotion);
    int curAnm = npc->getModel()->mAnm.mAnmId;
    int anm = data->mStart.mAnmId;
    if (anm == 0) {
        anm = npc->mAnmSet.mWaitAnm;
    }
    if (npc->getModel()->setAnm(anm, (m3d::playMode_e)data->mMode, 0.0f, 1.0f, prm->mMorph, FALSE)) {
        if (npc->mFace.isValid()) {
            npc->mFace.setAnmTex(npc, anm, m3d::PLAYMODE_INHERIT);
        }
        if (curAnm == 0x5C) {
            npc->getModel()->setLarmAnm(0x60, m3d::PLAYMODE_INHERIT, TRUE, 0.0f, 1.0f, 0.0f);
        } else if (curAnm == 0x67) {
            npc->getModel()->setLarmAnm(0x6B, m3d::PLAYMODE_INHERIT, FALSE, 0.0f, 1.0f, 0.0f);
        }
    }
    mEmotionMode = data->mMode;
    mVec3_c ofs = mVec3_c::Zero;
    mVec3_c ofsL = mVec3_c::Zero;
    mVec3_c ofsR = mVec3_c::Zero;
    npc->getManpuOfs(&ofs, &ofsL, &ofsR, data->mStart.mType);
    npc->mManpu.start(&data->mStart, &ofs, &ofsL, &ofsR);
    mCanChange = FALSE;
    return 1;
}

// 80020D3C
void dAcNpc_c::action_c::execEmotion(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    const emotionData_s *data = getEmotionData(mEmotion);
    if (data != NULL) {
        if (mEmotionMode == 1) {
            if (npc->getModel()->mAnm.isStop()) {
                const dAcNpc_c::manpuMgr_c::startData_s *loop = &data->mLoop;
                int anm = loop->mAnmId;
                if ((u32)anm < 0x1BC) {
                    npc->setAnm(anm, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE);
                    mVec3_c ofs = mVec3_c::Zero;
                    mVec3_c ofsL = mVec3_c::Zero;
                    mVec3_c ofsR = mVec3_c::Zero;
                    npc->getManpuOfs(&ofs, &ofsL, &ofsR, loop->mType);
                    npc->mManpu.start(loop, &ofs, &ofsL, &ofsR);
                    mEmotionMode = 0;
                } else if (anm == 0x1BC) {
                    mCanChange = TRUE;
                    mEmotionMode = 0;
                }
            }
        } else if (mEmotion == 0 && !mCanChange) {
            npc->getModel()->stopLarmAnm(0.0f);
            mCanChange = TRUE;
        }
    }
}

// 80020EFC
int dAcNpc_c::action_c::initAnm(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    reset();
    setAngle(npc->mAngle.y);
    setTurnSpeed(prm->mTurnSpeed);
    int anm = prm->mAnmId;
    if (npc->getModel()->setAnm(anm, (m3d::playMode_e)prm->mPlayMode, prm->mFrame, 1.0f, prm->mMorph, prm->mForce) && npc->mFace.isValid()) {
        npc->mFace.setAnmTex(npc, anm, m3d::PLAYMODE_INHERIT);
    }
    mCanChange = FALSE;
    if (npc->isLocalOwner()) {
        dNpcDaub_c *daub = fn_800EFD04(&npc->mNpcItem.mId);
        if (daub != NULL) {
            daub->set19(mActionId, mCurPrio);
            daub->setAct(anm, prm->mPlayMode, prm->mMorph, prm->mFrame);
        }
    }
    return 1;
}

// 80021018
void dAcNpc_c::action_c::postExecAnm(dAcNpc_c *npc) {
    getPrm();
    anm_c *anm = &npc->getModel()->mAnm;
    int mode = anm->mPlayMode;
    setAngle(npc->mAngle.y);
    BOOL end = FALSE;
    switch (mode) {
    case m3d::FORWARD_ONCE:
    case m3d::REVERSE_ONCE:
        end = anm->isStop();
        break;
    case m3d::FORWARD_LOOP:
    case m3d::REVERSE_LOOP:
        end = anm->checkFrame(0.0f);
        break;
    }
    if (end) {
        mCanChange = TRUE;
    }
}

