// 80022CE4
BOOL dAcNpc_c::action_c::updateChangeAnm(dAcNpc_c *npc, dItem::Item item, int anmId, BOOL unused) {
    anm_c *anm = &npc->getModel()->mAnm;
    actionPrm_c *prm = getPrm();
    BOOL ret = FALSE;
    if (anmId == anm->mAnmId) {
        if (anm->isStop()) {
            npc->setAnm(npc->mAnmSet.mWaitAnm, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE);
            ret = TRUE;
            npc->mLookAt.mReset = false;
        } else {
            anm->getFrame();
            BOOL medicine = FALSE;
            if (item.isValid()) {
                const dItem::BITM *bitm = dItem::infoBank_c::get()->getBITM(item);
                if (bitm != NULL && bitm->getKind() == dItem::KIND_MEDICINE) {
                    medicine = TRUE;
                }
            }
            if (!medicine && anm->checkFrame(24.0f)) {
                clothBase_c *cloth = npc->getCloth();
                if (cloth != NULL) {
                    nw4r::g3d::ResFile file(npc->getMdlResFile());
                    cloth->vt1C(file.GetResMdl(0));
                }
            } else if (anm->checkFrame(38.0f)) {
                createChangeEffect(npc->mPos, npc->mAngle.y);
            }
        }
    }
    return ret;
}

