// 80023C70
int dAcNpc_c::action_c::initChangeCloth(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    reset();
    setAngle(npc->mAngle.y);
    if (mSavedAnmId != 0x1BC) {
        npc->mAnmSet.setAnm0(mSavedAnmId);
        mSavedAnmId = 0x1BC;
    }

    BOOL isMedicine = FALSE;
    if (prm->mItem.isValid()) {
        const dItem::BITM *bitm = dItem::getBITM(prm->mItem.getId());
        if (bitm != NULL && bitm->getKind() == dItem::KIND_MEDICINE) {
            isMedicine = TRUE;
        }
    }

    if (!isMedicine && npc->getCloth() != NULL) {
        mStep = 0;
    } else {
        if (npc->getModel()->setAnm(0x5E, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE)) {
            if (npc->mFace.isValid()) {
                npc->mFace.setAnmTex(npc, 0x5E, m3d::PLAYMODE_INHERIT);
            }
            npc->getModel()->stopLarmAnm(prm->mMorph);
        }
        fn_80194CB0(npc);
        npc->mLookAt.mReset = true;
        startChangeSound(npc, prm->mItem);
        fn_80087790("af_ply_change", &npc->mPos, NULL, NULL);
        mStep = 1;
    }
    mCanChange = FALSE;
    return 1;
}

