// 80024B80
int dAcNpc_c::action_c::initEat(dAcNpc_c *npc) {
    if (fn_80194AEC()) {
        actionPrm_c *prm = getPrm();
        reset();
        setAngle(npc->mAngle.y);
        if (fn_80194AA0(0xA, npc, lbl_80751600)) {
            if (mSavedAnmId != 0x1BC) {
                npc->mAnmSet.setAnm0(mSavedAnmId);
                mSavedAnmId = 0x1BC;
            }
            int anmId = prm->mItem.isFish() ? 0x69 : 0x5F;
            if (npc->getModel()->setAnm(anmId, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE)) {
                if (npc->mFace.isValid()) {
                    npc->mFace.setAnmTex(npc, anmId, m3d::PLAYMODE_INHERIT);
                }
                npc->getModel()->stopLarmAnm(prm->mMorph);
            }
            if ((u32)prm->mEffectIdx < 2) {
                const char *name = l_eatFishEffect[prm->mEffectIdx];
                mVec3_c pos = npc->getNode13Pos();
                mAng3_c ang = mAng3_c::Zero;
                ang.y = npc->mAngle.y;
                if (!mEffect.create(name, &pos, &ang, NULL)) {
                    prm->mEffectIdx = 2;
                }
            }
            npc->mAudioObj.startSound(0x1738);
            npc->mLookAt.mReset = true;
            mStep = 1;
        } else {
            mStep = 0;
        }
        mCanChange = FALSE;
    }
    return 1;
}

