// 8002542C
int dAcNpc_c::action_c::initChangeCloth2(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    reset();
    setAngle(npc->mAngle.y);

    BOOL isMedicine = FALSE;
    if (prm->mItem.isValid()) {
        const dItem::BITM *bitm = dItem::getBITM(prm->mItem.getId());
        if (bitm != NULL && bitm->getKind() == dItem::KIND_MEDICINE) {
            isMedicine = TRUE;
        }
    }

    if (!isMedicine && npc->getCloth() != NULL) {
        mStep = 0;
    } else if (npc->getModel()->setAnm(0xFA, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE) &&
               npc->mFace.isValid()) {
        npc->mFace.setAnmTex(npc, 0xFA, m3d::PLAYMODE_INHERIT);
        mStep = 1;
        npc->mLookAt.mReset = true;
        startChangeSound(npc, prm->mItem);
        fn_80087790("af_ply_change", &npc->mPos, NULL, NULL);
    }
    mCanChange = FALSE;
    return 1;
}

// 800255C0
void dAcNpc_c::action_c::changeCloth2WaitCloth(dAcNpc_c *npc) {
    clothBase_c *cloth = npc->getCloth();
    actionPrm_c *prm = getPrm();
    if (cloth->vt24(npc)) {
        if (npc->getModel()->setAnm(0xFA, m3d::PLAYMODE_INHERIT, 0.0f, 1.0f, prm->mMorph, FALSE) && npc->mFace.isValid()) {
            npc->mFace.setAnmTex(npc, 0xFA, m3d::PLAYMODE_INHERIT);
        }
        npc->mLookAt.mReset = true;
        startChangeSound(npc, prm->mItem);
        fn_80087790("af_ply_change", &npc->mPos, NULL, NULL);
        mStep = 1;
    }
}

// 800256F8
void dAcNpc_c::action_c::changeCloth2WaitAnm(dAcNpc_c *npc) {
    actionPrm_c *prm = getPrm();
    if (updateChangeAnm(npc, prm->mItem, 0xFA, FALSE) != FALSE) {
        mStep = 2;
        mCanChange = TRUE;
    }
}

