BOOL dAcNpc_c::frontChk_c::checkStep(const mVec3_c *pos, f32 prevY, f32 *outY) {
    BOOL hit = FALSE;
    f32 y;
    if (isCurrentSceneAttr(0x10)) {
        y = dBGCF::getGroundY(pos, FALSE);
        if (dBGCF::getOpenNext(pos) != -1) {
            hit = TRUE;
        } else {
            f32 x = pos->x;
            f32 z = pos->z;
            f32 h = fn_800AA7F0((int)x >> 5, (int)z >> 5);
            if (h != y) {
                hit = TRUE;
            }
            y = h;
        }
    } else {
        dBGCF::groundChk_c chk(pos, 0, 0, 0);
        y = chk.getHeight(TRUE);
        if (chk.mWater != 0 ||
            (std::fabs(y - pos->y) >= 7.0f && (prevY == 0.0f || std::fabs(y - prevY) >= 7.0f)) ||
            dBGCF::checkColumn(pos, NULL, NULL, NULL)) {
            hit = TRUE;
        }
    }
    if (outY != NULL) {
        *outY = y;
    }
    return hit;
}

