static mVec3_c l_80564CA8[2] = {mVec3_c(7.0f, 0.0f, 15.0f), mVec3_c(-7.0f, 0.0f, 15.0f)};

void dAcNpc_c::frontChk_c::calc(dAcNpc_c *npc) {
    const mVec3_c *ofs = l_80564CA8;
    f32 *groundY = mGroundY;
    for (int i = 0; i < 2; i++) {
        mVec3_c p;
        p = *ofs;
        p.rotY(npc->mAngle3D.y);
        p.x += npc->mPos.x;
        p.y += npc->mPos.y;
        p.z += npc->mPos.z;
        if (checkStep(&p, *groundY, groundY)) {
            mHitFlags |= (1 << i);
        }
        ofs++;
        groundY++;
    }
}

