void dAcNpc_c::footstep_c::calc(dAcNpc_c *npc) {
    anm_c *anm;
    anmSet_c *set;
    s16 angY;
    f32 speed = npc->mSpeedF;
    s16 turn = npc->mAction.getTurnSpeed();
    angY = npc->mAngle.y.mAngle;
    if (mEnable && npc->mIsActive) {
        model_c *model = npc->getModel();
        anm = &model->mAnm;
        set = &npc->mAnmSet;
        int anmId = model->mAnm.mAnmId;
        if ((speed != 0.0f || (turn != 0 && angY != mPrevAngY)) &&
            (anmId == set->getAnm(1) || anmId == set->getAnm(2))) {
            if ((mPrevSpeed == 0.0f && speed != 0.0f) || (mPrevTurn == 0 && mPrevAngY != angY)) {
                setPrintL(npc);
                setPrintR(npc);
            } else if (anm->checkFrame(16.0f)) {
                setPrintL(npc);
                playSound(npc);
            } else if (anm->checkFrame(0.0f)) {
                setPrintR(npc);
                playSound(npc);
            }
        }
    }
    mPrevSpeed = speed;
    mPrevAngY = angY;
    mPrevTurn = turn;
}

